// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native Remotion spring and interpolate are perfect for a clean, minimalist UI motion graphic.

const { fontFamily: interFamily } = loadInter();



export type MotionFlagsProps = Record<string, any>;

const MotionFlags: React.FC<MotionFlagsProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  textColor = "#1a1a1a",
  durationInSeconds = 5,
  flags = [
    {
      image:
        "https://upload.wikimedia.org/wikipedia/en/a/a4/Flag_of_the_United_States.svg",
      label: "États-Unis",
    },
    {
      image:
        "https://upload.wikimedia.org/wikipedia/commons/5/5f/Flag_of_Quebec.svg",
      label: "Québec",
    },
    {
      image:
        "https://upload.wikimedia.org/wikipedia/en/c/c3/Flag_of_France.svg",
      label: "France",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Scale factors for responsive design
  const s = Math.min(width, height) / 1080;
  
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Dimensions (derived from canvas size)
  const itemHeight = height * 0.18;
  const flagWidth = itemHeight * 1.5;
  const gap = height * 0.06;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        gap: gap,
      }}
    >
      {flags.map((flag, index) => {
        // Stagger entrances by 15 frames each
        const delay = index * 15;
        
        const progress = spring({
          frame: frame - delay,
          fps,
          config: {
            damping: 14,
            stiffness: 100,
            mass: 0.8,
          },
        });

        const opacity = interpolate(progress, [0, 1], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        // Slide up slightly while fading in
        const translateY = interpolate(progress, [0, 1], [height * 0.1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        // Subtle scale in for a modern, fluid feel
        const scale = interpolate(progress, [0, 0.6, 1], [0.9, 1.02, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={index}
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              width: width * 0.45, // Fix container width to align text perfectly
              gap: width * 0.04,
              opacity,
              transform: `translateY(${translateY}px) scale(${scale})`,
              transition: "none",
            }}
          >
            {/* Flag Container */}
            <div
              style={{
                width: flagWidth,
                height: itemHeight,
                borderRadius: 16 * s,
                overflow: "hidden",
                boxShadow: `0 ${10 * s}px ${30 * s}px rgba(0,0,0,0.15)`,
                border: `${2 * s}px solid rgba(255,255,255,0.2)`,
                flexShrink: 0,
                transition: "none",
                backgroundColor: "#e0e0e0", // placeholder color before image loads
              }}
            >
              <Img
                src={flag.image}
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  display: "block",
                  transition: "none",
                }}
              />
            </div>

            {/* Label Container */}
            <div
              style={{
                fontFamily: interFamily,
                fontSize: height * 0.065,
                fontWeight: 600,
                color: textColor,
                letterSpacing: "-0.02em",
                transition: "none",
                // Drop shadow on text ensures readability if rendered over unknown backgrounds in transparent mode
                textShadow: `0 ${4 * s}px ${12 * s}px rgba(255,255,255,0.4)`,
              }}
            >
              {flag.label}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default MotionFlags;